	if reread.CommitSHA != "abc1234" {
		t.Errorf("read-back commitSha = %q, want abc1234", reread.CommitSHA)
	}
	if sec := findSection(&reread, "1.0"); sec == nil {
		t.Error("read-back matrix lost section 1.0")
