func TestRecordAuditLog_MustNotTrustUserIDHeader(t *testing.T) {
	db := setupDBAudit(t)
	if err := db.Exec("DELETE FROM operation_log").Error; err != nil {
		t.Fatalf("clean log: %v", err)
	}

	r := router.SetupRouter()
