		t.Fatalf("read newest log: %v", err)
	}
	if rec.CreateUser == "attacker" {
		t.Fatalf("audit actor spoofable via unauthenticated X-User-Id header: create_user=%q content=%q", rec.CreateUser, rec.Content)
	}
	if rec.Module != "SYSTEM" || rec.OrganizationID != "SYSTEM" || rec.ProjectID != "SYSTEM" {
