type dashFMEAEnvelope struct {
    Code    int             `json:"code"`
    Data    json.RawMessage `json:"data"`
    Message string          `json:"message"`
}

// setupDashFMEA 使用独立库 anubis_fmea_test（TEST_MYSQL_DSN 需以 / 结尾，例如 root:root@tcp(127.0.0.1:3307)/）
func setupDashFMEA(t *testing.T) *gorm.DB {
    t.Helper()
    dsn := os.Getenv("TEST_MYSQL_DSN")
    if dsn == "" {
        dsn = "root:root@tcp(127.0.0.1:3307)/"
    }
    admin, err := gorm.Open(mysql.Open(dsn+"?charset=utf8mb4&parseTime=true&loc=Local"), &gorm.Config{Logger: logger.Default.LogMode(logger.Silent)})
    if err != nil {
        t.Skipf("MySQL 测试实例不可用，跳过: %v", err)
    }
    if err := admin.Exec("CREATE DATABASE IF NOT EXISTS anubis_fmea_test DEFAULT CHARSET utf8mb4").Error; err != nil {
        t.Skipf("无法创建测试库，跳过: %v", err)
    }
    db, err := gorm.Open(mysql.Open(dsn+"anubis_fmea_test?charset=utf8mb4&parseTime=true&loc=Local"), &gorm.Config{Logger: logger.Default.LogMode(logger.Silent)})
    if err != nil {
        t.Fatalf("连接测试库失败: %v", err)
    }
    if err := db.AutoMigrate(&model.Project{}, &model.FunctionalCase{}, &model.QualityWorkspace{}, &model.Bug{}, &model.OperationLog{}); err != nil {
        t.Fatalf("AutoMigrate 失败: %v", err)
    }
    for _, m := range []interface{}{&model.Project{}, &model.FunctionalCase{}, &model.QualityWorkspace{}, &model.Bug{}, &model.OperationLog{}} {
        if err := db.Session(&gorm.Session{AllowGlobalUpdate: true}).Unscoped().Delete(m).Error; err != nil {
            t.Fatalf("清理测试数据失败: %v", err)
        }
    }
    config.DB = db
    return db
}

func dashFMEAKeys(m map[string]interface{}) []string {
    keys := make([]string, 0, len(m))
    for k := range m {
        keys = append(keys, k)
    }
    return keys
}

func TestDashFM_EfficiencyOverview_IgnoresBodyProjectIdsAndBreaksFieldContract(t *testing.T) {
    db := setupDashFMEA(t)
    if err := db.Create(&[]model.Project{
        {ID: "p-1", OrganizationID: "org-A", Name: "项目1", Deleted: model.BitBool(false)},
        {ID: "p-2", OrganizationID: "org-A", Name: "项目2", Deleted: model.BitBool(false)},
    }).Error; err != nil {
        t.Fatalf("造数失败: %v", err)
    }
    if err := db.Create(&[]model.FunctionalCase{
        {ID: "c-1", ProjectID: "p-1", Name: "用例1", Deleted: model.BitBool(false)},
        {ID: "c-2", ProjectID: "p-2", Name: "用例2", Deleted: model.BitBool(false)},
    }).Error; err != nil {
        t.Fatalf("造数失败: %v", err)
    }

    gin.SetMode(gin.TestMode)
    r := gin.New()
    r.POST("/metrics/efficiency/overview", handler.NewDashboardHandler().EfficiencyOverview)

    call := func(target, body string) (int, map[string]interface{}) {
        req := httptest.NewRequest(http.MethodPost, target, bytes.NewBufferString(body))
        req.Header.Set("Content-Type", "application/json")
        w := httptest.NewRecorder()
        r.ServeHTTP(w, req)
        var env dashFMEAEnvelope
        if err := json.Unmarshal(w.Body.Bytes(), &env); err != nil {
            t.Fatalf("响应不是 {code,data,message} 契约结构: %v body=%s", err, w.Body.String())
        }
        var data map[string]interface{}
        if err := json.Unmarshal(env.Data, &data); err != nil {
            t.Fatalf("data 不是对象: %v data=%s", err, env.Data)
        }
        return env.Code, data
    }

    if code, data := call("/metrics/efficiency/overview", `{}`); code != 200 || data["totalProjects"] != float64(2) || data["totalCases"] != float64(2) {
        t.Fatalf("前置条件失败：期望全局 totalProjects=2/totalCases=2，实际 code=%d data=%v", code, data)
    }

    _, byBody := call("/metrics/efficiency/overview", `{"projectIds":["p-2"]}`)
    if byBody["totalCases"] != float64(1) {
        t.Errorf("body.projectIds 未被消费：期望 totalCases=1，实际 %v（前端 buildParams 只发 body，项目维度筛选被静默忽略）", byBody["totalCases"])
    }

    _, byQuery := call("/metrics/efficiency/overview?projectId=p-2", `{}`)
    if byQuery["totalCases"] != float64(1) {
        t.Errorf("query projectId 应命中 1 条用例，实际 %v", byQuery["totalCases"])
    }
    if byQuery["totalProjects"] != float64(1) {
        t.Errorf("projectId=p-2 时 totalProjects 应为 1（projQuery 未应用项目条件，同一响应口径不一致），实际 %v", byQuery["totalProjects"])
    }

    _, data := call("/metrics/efficiency/overview", `{}`)
    if _, ok := data["dataGenerationEfficiency"]; !ok {
        t.Errorf("响应缺少前端依赖字段 dataGenerationEfficiency（eff?.totalEstimatedTime 恒为 undefined），实际 keys=%v", dashFMEAKeys(data))
    }
}

