type logFMEAEnvelope struct {
    Code    int             `json:"code"`
    Data    json.RawMessage `json:"data"`
    Message string          `json:"message"`
}

// logFMEAPage 对应 response.PageResult
type logFMEAPage struct {
    List       []map[string]interface{} `json:"list"`
    Total      int64                    `json:"total"`
    Current    int                      `json:"current"`
    PageSize   int                      `json:"pageSize"`
    TotalPages int64                    `json:"totalPages"`
}

// setupLogFMEA 使用独立库 anubis_fmea_test（TEST_MYSQL_DSN 需以 / 结尾）
func setupLogFMEA(t *testing.T) *gorm.DB {
    t.Helper()
    dsn := os.Getenv("TEST_MYSQL_DSN")
    if dsn == "" {
        dsn = "root:root@tcp(127.0.0.1:3307)/"
    }
    admin, err := gorm.Open(mysql.Open(dsn+"?charset=utf8mb4&parseTime=true&loc=Local"), &gorm.Config{Logger: logger.Default.LogMode(logger.Silent)})
    if err != nil {
        t.Skipf("MySQL 测试实例不可用，跳过: %v", err)
    }
    if err := admin.Exec("CREATE DATABASE IF NOT EXISTS anubis_fmea_test DEFAULT CHARSET utf8mb4").Error; err != nil {
        t.Skipf("无法创建测试库，跳过: %v", err)
    }
    db, err := gorm.Open(mysql.Open(dsn+"anubis_fmea_test?charset=utf8mb4&parseTime=true&loc=Local"), &gorm.Config{Logger: logger.Default.LogMode(logger.Silent)})
    if err != nil {
        t.Fatalf("连接测试库失败: %v", err)
    }
    if err := db.AutoMigrate(&model.OperationLog{}, &model.User{}, &model.Organization{}, &model.Project{}); err != nil {
        t.Fatalf("AutoMigrate 失败: %v", err)
    }
    for _, m := range []interface{}{&model.OperationLog{}, &model.User{}, &model.Organization{}, &model.Project{}} {
        if err := db.Session(&gorm.Session{AllowGlobalUpdate: true}).Unscoped().Delete(m).Error; err != nil {
            t.Fatalf("清理测试数据失败: %v", err)
        }
    }
    config.DB = db
    return db
}

func newLogFMEAPage(t *testing.T, body []byte) logFMEAPage {
    t.Helper()
    var env logFMEAEnvelope
    if err := json.Unmarshal(body, &env); err != nil {
        t.Fatalf("响应不是 {code,data,message} 契约结构: %v body=%s", err, body)
    }
    if env.Code != 200 {
        t.Fatalf("期望 code=200，实际 %d message=%s", env.Code, env.Message)
    }
    var page logFMEAPage
    if err := json.Unmarshal(env.Data, &page); err != nil {
        t.Fatalf("data 不是分页结构: %v data=%s", err, env.Data)
    }
    return page
}

func TestLogFM_SystemLogList_LeaksCrossOrganizationAuditTrail(t *testing.T) {
    db := setupLogFMEA(t)
    now := time.Now().UnixMilli()
    if err := db.Create(&[]model.OperationLog{
        {ID: 101, ProjectID: "proj-A", OrganizationID: "org-A", CreatedAt: now, CreateUser: "admin", SourceID: "s1", Type: "ADD", Module: "SYSTEM", Content: "org-A 审计"},
        {ID: 102, ProjectID: "proj-B", OrganizationID: "org-B", CreatedAt: now, CreateUser: "admin", SourceID: "s2", Type: "ADD", Module: "SYSTEM", Content: "org-B 机密审计"},
    }).Error; err != nil {
        t.Fatalf("造数失败: %v", err)
    }

    gin.SetMode(gin.TestMode)
    r := gin.New()
    r.POST("/operation/log/list", handler.NewLogHandler().SystemLogList)

    req := httptest.NewRequest(http.MethodPost, "/operation/log/list", bytes.NewBufferString(`{"current":1,"pageSize":10}`))
    req.Header.Set("Content-Type", "application/json")
    req.Header.Set("ORGANIZATION", "org-A")
    w := httptest.NewRecorder()
    r.ServeHTTP(w, req)

    if w.Code != http.StatusOK {
        t.Fatalf("期望 HTTP 200，实际 %d", w.Code)
    }
    page := newLogFMEAPage(t, w.Body.Bytes())
    for _, item := range page.List {
        if fmt.Sprint(item["organizationId"]) != "org-A" {
            t.Errorf("跨租户泄漏：ORGANIZATION=org-A 的无凭据请求读到了 organizationId=%v 的审计日志（期望仅 org-A）", item["organizationId"])
        }
    }
    if page.Total != 1 {
        t.Errorf("期望 total=1（仅 org-A），实际 total=%d（当前实现无租户条件，命中全表）", page.Total)
    }
}

