func TestLogFM_ListQueryParams_ContentFilterDroppedAndBindErrorResetsPaging(t *testing.T) {
    db := setupLogFMEA(t)
    now := time.Now().UnixMilli()
    if err := db.Create(&[]model.OperationLog{
        {ID: 401, ProjectID: "p1", OrganizationID: "org-A", CreatedAt: now, CreateUser: "admin", Type: "ADD", Module: "SYSTEM", Content: "MATCH-TARGET"},
        {ID: 402, ProjectID: "p1", OrganizationID: "org-A", CreatedAt: now, CreateUser: "admin", Type: "ADD", Module: "SYSTEM", Content: "OTHER"},
    }).Error; err != nil {
        t.Fatalf("造数失败: %v", err)
    }

    gin.SetMode(gin.TestMode)
    r := gin.New()
    r.POST("/operation/log/list", handler.NewLogHandler().SystemLogList)

    call := func(body string) logFMEAPage {
        req := httptest.NewRequest(http.MethodPost, "/operation/log/list", bytes.NewBufferString(body))
        req.Header.Set("Content-Type", "application/json")
        w := httptest.NewRecorder()
        r.ServeHTTP(w, req)
        return newLogFMEAPage(t, w.Body.Bytes())
    }

    byContent := call(`{"current":1,"pageSize":10,"content":"MATCH-TARGET"}`)
    if byContent.Total != 1 {
        t.Errorf("content 过滤应命中 1 条，实际 total=%d（前端 formatQueryParams 下发的 content 从未进入 Where）", byContent.Total)
    }

    reset := call(`{"current":3,"pageSize":5,"startTime":"not-a-number"}`)
    if reset.Current != 3 || reset.PageSize != 5 {
        t.Errorf("绑定失败后分页被强制重置，期望回显 current=3/pageSize=5，实际 current=%d pageSize=%d", reset.Current, reset.PageSize)
    }

    msFiltered := call(fmt.Sprintf(`{"current":1,"pageSize":10,"startTime":%d}`, now-1000))
    secondsFiltered := call(fmt.Sprintf(`{"current":1,"pageSize":10,"startTime":%d}`, (now-1000)/1000))
    if msFiltered.Total != secondsFiltered.Total {
        t.Errorf("时间戳单位未归一化：毫秒入参 total=%d 而秒级入参 total=%d（秒级被当成毫秒，过滤静默失效）", msFiltered.Total, secondsFiltered.Total)
    }
}

